budget.content:
{
  "schema_version": "ctp-research-agent-decision-v1",
  "agent_name": "budget",
  "summary": "评估两人从上海出发、2026-08-07在杭州游玩2天（2人、2天、含往返城际交通）3000元总预算的可行性。使用离线预算计算器结果（preview）和上游行程/景点决策，核对费用项并给出预算可行性结论、要点说明、风险与推荐总额。",
  "decisions": {
    "feasibility": {
      "is_feasible": true,
      "justification": "离线 budget_calculator 结果表明：在所请求的预算范围（total 3000元，包含来回交通与本地开销）下，按中等消费水平（selected scheme E，经济基线）估算总支出约1586元；预计实际消费约1472元，剩余预算约1414元，预算充足且有10%应急金约114元。计算已包含往返城际交通（intercity_transport_cost 332元）。因此在不提高酒店/餐饮档次且按公共交通与经济酒店的假设下，3000元是可行且宽裕的。"
    },
    "budget_notes": {
      "source_evidence": "budget_calculator (offline preview) and upstream attraction/itinerary agents",
      "included_costs": [
        "往返上海—杭州城际交通（已计，preview 显示 intercity_transport_cost: 332.0 元）",
        "本地交通、门票、餐饮、住宿按经济/中等档估算（budget policy E: economy hotel & food, public_transit）",
        "应急预留（contingency）约 114 元"
      ],
      "key_assumptions": [
        "使用 budget_calculator 中的候选方案 E（economic baseline），即酒店与餐饮采用 economy 档；若显著提高酒店或餐饮档次，预算需上调。",
        "行程以离线 itinerary 建议为基础（day1: 灵隐/清河坊；day2: 博物馆/雷峰塔），但预算 evidence 中 attractions 列表略有差异，预算已覆盖常见门票/交通与两天住宿与餐饮的经济估计。",
        "公共交通为主要城内出行方式；不包含奢侈购物或额外付费体验（如包船、包车等）。"
